using Godot;
using System;
using System.IO;
using System.Linq;
public partial class MigrationScene {
 void BuildUi(){NewHud();}
 void UpdateHud(){ComicHud();}
 VBoxContainer Panel(string title){coopMenu="";if(menu!=null){ui.RemoveChild(menu);menu.QueueFree();}paused=true;if(ambience!=null)ambience.StreamPaused=true;Input.MouseMode=Input.MouseModeEnum.Visible;menu=new PanelContainer{Position=new Vector2(160,30),Size=new Vector2(960,650),Theme=comicTheme};ui.AddChild(menu);var margin=new MarginContainer();foreach(string key in new[]{"margin_left","margin_top","margin_right","margin_bottom"})margin.AddThemeConstantOverride(key,18);menu.AddChild(margin);var box=new VBoxContainer();box.AddThemeConstantOverride("separation",9);margin.AddChild(box);var heading=new Label{Text=title};heading.AddThemeFontSizeOverride("font_size",23);heading.AddThemeColorOverride("font_color",new Color(.88f,.75f,.48f));box.AddChild(heading);box.AddChild(new HSeparator());return box;}
 void Text(VBoxContainer box,string text){box.AddChild(new Label{Text=text,AutowrapMode=TextServer.AutowrapMode.WordSmart,CustomMinimumSize=new Vector2(880,0)});}
 void Button(Container box,string title,Action action){var button=new Godot.Button{Text=title,TooltipText=title,ClipText=box is GridContainer,CustomMinimumSize=box is GridContainer?new Vector2(430,34):Vector2.Zero,MouseDefaultCursorShape=Control.CursorShape.PointingHand};box.AddChild(button);button.Pressed+=action;}
 void CloseMenu(){coopMenu="";if(menu!=null){ui.RemoveChild(menu);menu.QueueFree();menu=null;}paused=false;if(ambience!=null)ambience.StreamPaused=muted;Input.MouseMode=testing?Input.MouseModeEnum.Visible:Input.MouseModeEnum.Captured;}
 void ShowCrafting(){ComicCrafting();}
 void ShowEquipment(){ComicEquipment();}
 void ShowSkills(){ShowProgression();}
 void ShowCamps(){var b=Panel("SLEEPING BAGS / RESPAWN / TRAVEL");coopMenu="camps";Text(b,"Bag kits "+game.Life.Bags+" / travel needs daylight, no wounds, safe camps, 1 food + 1 water + 25 energy. Ten-minute cooldown.");Button(b,"SURVIVOR COMMUNITY / F7",()=>ShowCommunity());Button(b,"PLACE BAG HERE",()=>{if(!CoopRequest("bag"))game.AddBag(player.Position.X,player.Position.Z,CampSafe);SyncCampObjects();ShowCamps();});var sc=new ScrollContainer{CustomMinimumSize=new Vector2(880,270)};b.AddChild(sc);var rows=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};sc.AddChild(rows);foreach(var camp in game.Life.Camps.Where(c=>c.Seed==game.Save.Seed)){var copy=camp;Text(rows,(camp.Id==game.Life.Respawn?"[RESPAWN] ":"")+"Camp "+(int)camp.X+", "+(int)camp.Z);Button(rows,"BIND RESPAWN",()=>{if(!CoopRequest("bind",copy.Id))game.Change(()=>game.Life.Respawn=copy.Id);ShowCamps();});Button(rows,"TRAVEL",()=>{if(CoopActive){game.Notice="Fast travel is disabled during co-op; explore together.";ShowCamps();return;}game.Save.X=player.Position.X;game.Save.Z=player.Position.Z;if(game.Travel(copy,CampSafe)=="Travelled"){Teleport(game.Save.X,game.Save.Z);ClearEnemies();}ShowCamps();});}Text(b,game.Notice);Button(b,"REST AT CURRENT BAG",()=>{if(CoopRequest("rest"))return;var camp=game.Life.Camps.Find(c=>c.Seed==game.Save.Seed&&ExpeditionGame.Distance(c.X,c.Z,player.Position.X,player.Position.Z)<4);if(camp!=null&&CampSafe(camp)&&!game.Life.Wounds.Exists(w=>!w.Patched)){game.Change(()=>game.Rested());game.Notice="Rested";}else game.Notice="Stand at a safe bag and patch bleeding first";ShowCamps();});Button(b,"BACK",CloseMenu);}
 void ShowPause(){var b=Panel(CoopActive?"EXPEDITION / ONLINE (WORLD CONTINUES)":"EXPEDITION / PAUSED");Text(b,"Solo menus pause the world. Online menus keep needs, wounds and threats active.\nF8 / host or join Godot co-op. Saves remain outside game update folders.");Button(b,"RESUME",CloseMenu);Button(b,"MUSIC VOLUME",ShowMusicSettings);Button(b,"YOUR JOURNEY / BOSSES AND FIELD GUIDE",ShowCampaignGuide);Button(b,"MULTIPLAYER / HOST OR JOIN",ShowMultiplayer);Button(b,"RETURN TO SOUTHEAST TRAILHEAD",()=>{if(CoopActive){game.Notice="Leave co-op before relocating.";ShowPause();return;}ExitDungeon(false);ClearEnemies();Teleport(ExpeditionWorld.SpawnX,ExpeditionWorld.SpawnZ);game.Persist();CloseMenu();});Button(b,"SAVE",()=>{game.Persist();ShowPause();});Button(b,"IMPORT OLD EXPEDITION CHARACTER (replaces this character; previous save kept as .bak)",ImportDialog);var seed=new SpinBox{MinValue=1,MaxValue=999999,Value=game.Save.Seed};b.AddChild(seed);Button(b,"OPEN WORLD SEED (keeps character, per-seed builds and world changes)",()=>{if(CoopActive){game.Notice="Leave co-op before switching worlds.";ShowPause();return;}ExitDungeon(false);game.Change(()=>{game.Save.Seed=(int)seed.Value;game.Save.X=ExpeditionWorld.SpawnX;game.Save.Z=ExpeditionWorld.SpawnZ;game.Normalize();});ClearEnemies();ClearChildren(worldRoot);props.Clear();uniqueObjects.Clear();RebuildTerrain();SyncStructures();Teleport(ExpeditionWorld.SpawnX,ExpeditionWorld.SpawnZ);CloseMenu();});Text(b,game.Notice);Button(b,"QUIT",()=>{if(CoopActive)StopCoop("Session closed");game.Persist();GetTree().Quit();});}
 void ImportDialog(){if(CoopActive){game.Notice="Leave co-op before importing a character.";ShowPause();return;}var fd=new FileDialog{FileMode=FileDialog.FileModeEnum.OpenFile,Access=FileDialog.AccessEnum.Filesystem,Title="Select legacy profiles/expedition-loot.json"};fd.Filters=new[]{"*.json ; Expedition character profile"};ui.AddChild(fd);fd.FileSelected+=path=>{try{string worlds=Path.Combine(Path.GetDirectoryName(Path.GetDirectoryName(path)),"worlds");if(game.ImportLegacy(path,worlds)){ExitDungeon(false);ClearEnemies();ClearChildren(worldRoot);props.Clear();uniqueObjects.Clear();RebuildTerrain();SyncStructures();Teleport(ExpeditionWorld.SpawnX,ExpeditionWorld.SpawnZ);}ShowPause();}catch(Exception ex){game.Notice="Import failed / "+ex.Message;ShowPause();}fd.QueueFree();};fd.Canceled+=()=>fd.QueueFree();fd.PopupCentered(new Vector2I(900,600));}
 void ShowMap(){var b=Panel("SOUTH BLOCK / SEED "+game.Save.Seed);var map=new ExpeditionMapCanvas{World=game.World,PlayerPosition=player.Position,CustomMinimumSize=new Vector2(880,400)};b.AddChild(map);Button(b,"BOSS LOCATIONS / JOURNEY",ShowCampaignGuide);Button(b,"TOGGLE SPAWN HEATMAP",()=>{map.Heat=!map.Heat;map.QueueRedraw();});Button(b,"HEATMAP: SWITCH DAY / NIGHT",()=>{map.NightHeat=!map.NightHeat;map.Heat=true;map.QueueRedraw();});Text(b,"Southeast trailhead > northwest woodland > outskirts > city > city depths. Green = quiet; amber/red = increasing spawn pressure. River crossing closed.");Button(b,"BACK",CloseMenu);}
 void ShowRelay(){var b=Panel("EXISTING TLS RELAY / CONNECTION PROBE");Text(b,"Transport retained on TCP 28747. This tests connectivity only; Expedition world synchronization is not implemented.");var address=new LineEdit{PlaceholderText="Relay address"};var pin=new LineEdit{PlaceholderText="Certificate SHA256 fingerprint"};b.AddChild(address);b.AddChild(pin);Button(b,"CONNECT",()=>{relay?.Dispose();relay=new RelayLink();relay.Connect(new RelayConfig{Address=address.Text.Trim(),CertificateSha256=pin.Text.Trim(),Port=28747});CloseMenu();});Button(b,"BACK",CloseMenu);}
 void ShowLetter(int kind=1){var b=Panel(JournalText.SceneNames[kind]);Text(b,JournalText.SceneNotes[kind]);Button(b,"BACK",CloseMenu);}
 void ShowJournal(){var frame=Panel("FRAGMENTS / JOURNAL");Button(frame,"FIELD GUIDE / EXPLORATION RECORD",ShowFieldGuide);var scroll=new ScrollContainer{CustomMinimumSize=new(900,470)};frame.AddChild(scroll);var b=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};scroll.AddChild(b);Button(b,"THE SOUTH BANK / YOUR JOURNEY",ShowCampaignGuide);EncounterJournal(b);if(game.Profile.Journal.Seen.Exists(id=>id.StartsWith("crash/")))Button(b,"SO I WON'T GO ALONE",ShowCrashJournal);if(game.Profile.Journal.Seen.Contains("checkpoint/room"))Button(b,"THE PRICE OF CROSSING / THE LOCKED ROOM",()=>{var page=Panel("THE PRICE OF CROSSING");Text(page,"Three starving survivors charged a food toll on a bridge. Their own bowls were empty. The provisions went through a feeding slot to children in a locked room.\n\nA traveller begged to keep his pack. The guards told him to put it down.");Button(page,"BACK",CloseMenu);});if(game.Profile.Journal.Seen.Contains("birthday/sammy"))Button(b,"SAMMY'S NINTH BIRTHDAY",ShowBirthdayNote);for(int page=0;page<4;page++){int copy=page;if(game.Profile.Journal.Seen.Contains("last-letter/"+page))Button(b,LastLetterTitles[page],()=>ShowLastLetter(copy));}if(game.Profile.Journal.Seen.Contains(FeverJournal))Button(b,"JUST A FEVER / REMEMBERED",()=>ShowFeverNotebook(true));if(game.Profile.Journal.Seen.Contains(WoodlandJournal))Button(b,"THE FIRST FISH / WOODLAND CAMP",ShowWoodlandJournal);Text(b,game.Profile.Journal.Seen.Count+" recovered fragments. Search abandoned locations with F.");var kinds=new System.Collections.Generic.HashSet<int>();foreach(string id in game.Profile.Journal.Seen){if(id.StartsWith("crash/")||id.StartsWith("checkpoint/")||id.StartsWith("birthday/")||id.StartsWith("last-letter/")||id.StartsWith("fever/")||id.StartsWith("family/")||id.StartsWith("mill-note/"))continue;int kind;string tail=id.Substring(id.LastIndexOf('/')+1);if(int.TryParse(tail,out kind)&&kind>=0&&kind<6)kinds.Add(kind);else if(id.EndsWith("/letter"))kinds.Add(1);}foreach(int kind in kinds){int copy=kind;Button(b,JournalText.SceneNames[kind],()=>ShowLetter(copy));}for(int i=0;i<FamilyTitles.Length;i++){int copy=i;if(game.Profile.Journal.Seen.Contains("family/note/"+i))Button(b,FamilyTitles[i],()=>ShowFamilyNote(copy));}for(int i=0;i<MillNotes.Length;i++){int copy=i;if(game.Profile.Journal.Seen.Contains("mill-note/"+i))Button(b,MillNoteTitles[i],()=>ShowMillNote(copy));}Button(frame,"BACK",CloseMenu);}
}
internal partial class ExpeditionMapCanvas:Control {
 void DrawLetterMarkers(){double cx=ExpeditionLastLetter.ChurchX(World);DrawCircle(Map(cx,ExpeditionLastLetter.ChurchZ),5,Colors.LightBlue);DrawString(ThemeDB.FallbackFont,Map(cx,ExpeditionLastLetter.ChurchZ)+new Vector2(8,0),"ST. BRIGID'S",HorizontalAlignment.Left,-1,11,Colors.LightBlue);if(World.Changes?.LastLetter?.Stage==1){var p=Map(ExpeditionLastLetter.HomeX(World),ExpeditionLastLetter.HomeZ);DrawCircle(p,6,Colors.Gold);DrawString(ThemeDB.FallbackFont,p+new Vector2(-135,14),"LETTER / SAMUEL",HorizontalAlignment.Left,-1,11,Colors.Gold);}}

 internal ExpeditionWorld World;internal Vector3 PlayerPosition;internal bool Heat,NightHeat;
 Vector2 Map(double x,double z){return new Vector2((float)((x+1600)/3200*Size.X),(float)((z+2850)/3200*Size.Y));}
 public override void _Draw(){if(World==null)return;Color[] colors={Colors.Black,new Color(.41f,.49f,.29f),new Color(.18f,.33f,.22f),new Color(.48f,.39f,.26f),new Color(.36f,.38f,.39f)};for(int x=-1600;x<1600;x+=64)for(int z=-2850;z<350;z+=64){Color c=World.IsRiver(x,z)?new Color(.13f,.30f,.43f):!World.Playable(x,z)?new Color(.14f,.16f,.18f):colors[World.Tier(x,z)];if(World.Playable(x,z)&&!World.IsRiver(x,z)){if(Heat){float heat=(float)World.SpawnHeat(x+32,z+32,NightHeat);c=new Color(.14f,.34f,.25f).Lerp(new Color(.85f,.17f,.10f),heat);}else c*=.75f+(float)Math.Clamp(World.Height(x,z)/80,0,.45);}DrawRect(new Rect2(Map(x,z),new Vector2(Size.X/50+1,Size.Y/50+1)),c);}for(int z=-2400;z<300;z+=32)DrawLine(Map(World.RouteX(z),z),Map(World.RouteX(z+32),z+32),new Color(.72f,.64f,.43f),2);DrawLivingMap();DrawLetterMarkers();DrawCircle(Map(World.RouteX(-930)+55,-930),5,Colors.LightBlue);DrawString(ThemeDB.FallbackFont,Map(World.RouteX(-930)+55,-930)+new Vector2(8,0),"WILLOW HOUSE",HorizontalAlignment.Left,-1,11,Colors.LightBlue);DrawCircle(Map(World.RouteX(-780)+90,-780),6,new Color(.85f,.35f,.12f));DrawString(ThemeDB.FallbackFont,Map(World.RouteX(-780)+90,-780)+new Vector2(9,0),"LUMBER MILL",HorizontalAlignment.Left,-1,11,Colors.Orange);if(World.Changes?.Community is ExpeditionCommunity camp){foreach(var n in camp.Survivors)if(!n.Member){DrawCircle(Map(n.X,n.Z),5,Colors.Cyan);DrawString(ThemeDB.FallbackFont,Map(n.X,n.Z)+new Vector2(8,0),"RESCUE / "+n.Name,HorizontalAlignment.Left,-1,10,Colors.Cyan);}if(camp.Established){DrawCircle(Map(camp.X,camp.Z),6,Colors.LightGreen);DrawString(ThemeDB.FallbackFont,Map(camp.X,camp.Z)+new Vector2(8,0),"YOUR COMMUNITY",HorizontalAlignment.Left,-1,11,Colors.LightGreen);}}foreach(var d in ExpeditionDungeon.Nearby(World,0,0))DrawCircle(Map(d.X,d.Z),4,Colors.Orange);DrawCircle(Map(ExpeditionWorld.SpawnX,ExpeditionWorld.SpawnZ),7,Colors.LightGreen);DrawString(ThemeDB.FallbackFont,Map(ExpeditionWorld.SpawnX,ExpeditionWorld.SpawnZ)+new Vector2(-130,-10),"SOUTHEAST START",HorizontalAlignment.Left,-1,13,Colors.White);DrawString(ThemeDB.FallbackFont,new Vector2(12,20),Heat?(NightHeat?"SPAWN PRESSURE / NIGHT":"SPAWN PRESSURE / DAY"):"NORTH / TERRAIN & PROGRESSION",HorizontalAlignment.Left,-1,13,Colors.White);DrawCircle(Map(PlayerPosition.X,PlayerPosition.Z),5,Colors.White);}
}
